import{_ as s,o as e,c as i,a4 as t}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"基于规则 / 基于代价优化 (RBO/CBO)","description":"","frontmatter":{},"headers":[],"relativePath":"databases/optimization/rbo-cbo.md","filePath":"databases/optimization/rbo-cbo.md","lastUpdated":1788475713000}'),n={name:"databases/optimization/rbo-cbo.md"};function l(o,a,p,r,c,d){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="基于规则-基于代价优化-rbo-cbo" tabindex="-1">基于规则 / 基于代价优化 (RBO/CBO) <a class="header-anchor" href="#基于规则-基于代价优化-rbo-cbo" aria-label="Permalink to &quot;基于规则 / 基于代价优化 (RBO/CBO)&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>Planner = 规则改写 (RBO) + 代价估算 (CBO) + plan 搜索。RBO 做无成本的重写（谓词下推、子查询展开、常量折叠）；CBO 基于统计（MCV、histogram、n_distinct、selectivity）做 cost 模型选最低 cost plan。本节从 SQL 文本走到 plan tree：parser → rewriter → planner → executor 完整结构、世界各国主流 DB 的 planner 差异、Cascades 框架（SQL Server / Apache Calcite）与火山模型 vs 向量化的根本区别。</p><hr><h2 id="一、pipeline-全流程" tabindex="-1">一、Pipeline 全流程 <a class="header-anchor" href="#一、pipeline-全流程" aria-label="Permalink to &quot;一、Pipeline 全流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SQL Text</span></span>
<span class="line"><span>  ↓ lexer / parser (PG: scan.l + gram.y, MySQL: yacc++)</span></span>
<span class="line"><span>Query Tree (AST)</span></span>
<span class="line"><span>  ↓ Rewriter (RBO) — view expansion, constant folding, predicate simplification </span></span>
<span class="line"><span>Logical Plan Tree</span></span>
<span class="line"><span>  ↓ Planner (CBO) — selectivity estimation, cost model, search engine (DP / Cascades)</span></span>
<span class="line"><span>Physical Plan Tree</span></span>
<span class="line"><span>  ↓ Executor — pipelined / vectorized</span></span>
<span class="line"><span>Result rows</span></span></code></pre></div><p>PG 14+ planner 直接重写为 physical operator，把 transformation 与 cost 估计混合迭代。Apache Calcite（Hive、Flink、Beam 等）用 Cascades-volcano 风格，可 set-based 规则搜索。</p><hr><h2 id="二、rbo-变换清单" tabindex="-1">二、RBO 变换清单 <a class="header-anchor" href="#二、rbo-变换清单" aria-label="Permalink to &quot;二、RBO 变换清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>规则</th><th>作用</th></tr></thead><tbody><tr><td>View expansion</td><td>视图合并</td></tr><tr><td>Constant folding</td><td><code>1+1 &gt; 2</code> → TRUE/FALSE</td></tr><tr><td>Predicate pushdown</td><td><code>∏(σ(p(R)))</code> → <code>σ(p(∏(R)))</code></td></tr><tr><td>Sub-query flattening</td><td><code>WHERE x IN (SELECT ...)</code> → SEMI-JOIN</td></tr><tr><td>Sub-query decorrelation</td><td><code>Correlated EXISTS</code> → <code>SEMI JOIN</code></td></tr><tr><td>OUTER → INNER simplification</td><td><code>L JOIN A ON ... WHERE A.x NOT NULL</code> → INNER</td></tr><tr><td>Common subexpression elimination</td><td>重复表达式去重</td></tr><tr><td>OR → UNION ALL</td><td><code>WHERE a=1 OR b=2</code> 不可走两个 index → UNION ALL 走</td></tr><tr><td>CTE inline</td><td>PG 12+, MATERIALIZED marker</td></tr><tr><td>Dead code removal</td><td><code>SELECT * WHERE 1=0</code> → EMPTY</td></tr><tr><td>Distinct pushdown</td><td>DISTINCT 在 JOIN 中推下</td></tr></tbody></table><p>RBO 是 deterministic——不依赖 statistics，只做正确变换。然后给 CBO 优化。</p><hr><h2 id="三、cbo-核心模块" tabindex="-1">三、CBO 核心模块 <a class="header-anchor" href="#三、cbo-核心模块" aria-label="Permalink to &quot;三、CBO 核心模块&quot;">​</a></h2><h3 id="_3-1-statistics" tabindex="-1">3.1 Statistics <a class="header-anchor" href="#_3-1-statistics" aria-label="Permalink to &quot;3.1 Statistics&quot;">​</a></h3><p>PG <code>pg_statistics</code> (per-column):</p><ul><li><code>most_common_vals</code> / <code>most_common_freqs</code> — 高频值分布</li><li><code>histogram_bounds</code> — 等频直方图 (default_statistics_target 100 buckets)</li><li><code>n_distinct</code> — 唯一值数（负数表示比例）</li><li><code>null_frac</code> — NULL 比例</li><li><code>correlation</code> — 物理排序 vs 列值相关度 (用于 BRIN 与 ORDER BY index seek)</li></ul><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pg_stats </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tablename </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;users&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>MySQL 8.0+ 也类似：<code>ANALYZE</code> 拿 histogram (<code>information_schema.column_statistics</code>)。</p><h3 id="_3-2-selectivity-estimation" tabindex="-1">3.2 Selectivity Estimation <a class="header-anchor" href="#_3-2-selectivity-estimation" aria-label="Permalink to &quot;3.2 Selectivity Estimation&quot;">​</a></h3><p>等值 sel：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sel(col = value) =</span></span>
<span class="line"><span>  if value in MCV → MCV freq</span></span>
<span class="line"><span>  else 1 / max(n_distinct, 1)</span></span></code></pre></div><p>范围 sel：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sel(col between a and b) =</span></span>
<span class="line"><span>  if histogram available → [a,b] 内 bucket count</span></span>
<span class="line"><span>  else default 1/3 (rough)</span></span></code></pre></div><p>JOIN sel：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sel(R.a join S.b) = 1 / max(ndistinct(a), ndistinct(b))</span></span>
<span class="line"><span>                   if both unique (1:1) → 1 / max</span></span>
<span class="line"><span>                   if FK (1:N) → 1 / N_unique_of_major</span></span></code></pre></div><p>复合 sel：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sel(p1 AND p2) = sel(p1) × sel(p2) × dependent_factor</span></span>
<span class="line"><span>sel(p1 OR p2) = sel(p1) + sel(p2) - sel(p1 AND p2)</span></span></code></pre></div><p>PG <code>AND</code> 默认 <code>sel(p1) × sel(p2) × 0.5</code>（不可独立时）。</p><h3 id="_3-3-cost-model" tabindex="-1">3.3 Cost Model <a class="header-anchor" href="#_3-3-cost-model" aria-label="Permalink to &quot;3.3 Cost Model&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cost = seq_page_cost × num_seq_pages</span></span>
<span class="line"><span>     + random_page_cost × num_rand_pages</span></span>
<span class="line"><span>     + cpu_tuple_cost × num_rows</span></span>
<span class="line"><span>     + cpu_index_tuple_cost × num_index_rows</span></span>
<span class="line"><span>     + cpu_operator_cost × num_ops</span></span>
<span class="line"><span>     + parallel_setup_cost × 1 (if parallel workers)</span></span>
<span class="line"><span>     + parallel_tuple_cost × num_tuples</span></span></code></pre></div><p>PG 默认 (postgresql.conf):</p><ul><li><code>seq_page_cost = 1</code></li><li><code>random_page_cost = 4</code> (机械盘合适；SSD 应调 1.1-1.5)</li><li><code>cpu_tuple_cost = 0.01</code></li><li><code>cpu_index_tuple_cost = 0.005</code></li><li><code>cpu_operator_cost = 0.0025</code></li><li><code>parallel_setup_cost = 1000</code></li><li><code>parallel_tuple_cost = 0.1</code></li><li><code>effective_cache_size = 4GB</code> ← planner 假设 cache 大小（不分配），影响规划偏向</li></ul><p>调小 effective_cache_size → planner 偏 seq scan。 SSD 极推：<code>random_page_cost = 1.1, effective_cache_size = RAM × 0.7</code>。</p><hr><h2 id="四、plan-search" tabindex="-1">四、Plan Search <a class="header-anchor" href="#四、plan-search" aria-label="Permalink to &quot;四、Plan Search&quot;">​</a></h2><h3 id="_4-1-bottom-up-dp-system-r-风格" tabindex="-1">4.1 Bottom-up DP (System-R 风格) <a class="header-anchor" href="#_4-1-bottom-up-dp-system-r-风格" aria-label="Permalink to &quot;4.1 Bottom-up DP (System-R 风格)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DPsize 1 = base_tables optimal plan</span></span>
<span class="line"><span>DPsize k = min(DPsize k-1 join new base_table)</span></span>
<span class="line"><span>       考虑所有连接顺序 × join 算法 (hash/merge/loop)</span></span>
<span class="line"><span>       cost = already_seen_cost + new_join_cost</span></span></code></pre></div><p>复杂度 O(3^N) — join reorder，N 表少时 fast (N&lt;15)。</p><h3 id="_4-2-postgresql-geqo" tabindex="-1">4.2 PostgreSQL: GEQO <a class="header-anchor" href="#_4-2-postgresql-geqo" aria-label="Permalink to &quot;4.2 PostgreSQL: GEQO&quot;">​</a></h3><p><code>geqo_threshold = 12</code> (default)，N ≥ 12 表时切遗传算法：</p><ul><li>join order 编为 permutation</li><li>模拟进化 = mutation + crossover + selection 数千代</li><li>100-1000 倍快但非最优</li></ul><p>BI 工具跑出 N 表 join → query 性能差。临时关：<code>SET geqo = off</code>。</p><h3 id="_4-3-cascades-volcano" tabindex="-1">4.3 Cascades / Volcano <a class="header-anchor" href="#_4-3-cascades-volcano" aria-label="Permalink to &quot;4.3 Cascades / Volcano&quot;">​</a></h3><p>Cascades (Goetz Graefe, 1995) 是 top-down 规则驱动的 plan 搜索：</p><ul><li>任务栈：transform goal, implement goal, optimize goal</li><li>引用替代 copy：低内存开销</li><li>memo 数据结构存储所有 plan choices</li><li>规则集可扩展</li></ul><p>应用：</p><ul><li>SQL Server optimizer (微软内部 Cascades)</li><li>Apache Calcite (Hive、Flink、Beam)</li><li>CockroachDB (Moruit/Go 版本)</li><li>Spark Catalyst (类似 Cascades 模式)</li></ul><p>Cascades vs DP：</p><ul><li>DP 仅 join reorder，Cascades 可带所有物理算子选择</li><li>Cascades 慢但灵活 → 大数据业务偏好</li></ul><hr><h2 id="五、特殊情况" tabindex="-1">五、特殊情况 <a class="header-anchor" href="#五、特殊情况" aria-label="Permalink to &quot;五、特殊情况&quot;">​</a></h2><h3 id="_5-1-partition-pruning" tabindex="-1">5.1 Partition Pruning <a class="header-anchor" href="#_5-1-partition-pruning" aria-label="Permalink to &quot;5.1 Partition Pruning&quot;">​</a></h3><p>分区表查询时只扫匹配分区：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (created_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">timestamptz</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ...) </span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  PARTITION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> BY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> RANGE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (created_at);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> events_2024_01</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> PARTITION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OF events</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  FOR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> VALUES</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;2024-01-01&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;2024-02-01&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> events </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> created_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;2024-01-15&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 仅扫 events_2024_01</span></span></code></pre></div><p>PG 11+ 也支持运行时 execution-time pruning：动态 <code>parameter</code> 时也能 prune。</p><h3 id="_5-2-parallel-query" tabindex="-1">5.2 Parallel Query <a class="header-anchor" href="#_5-2-parallel-query" aria-label="Permalink to &quot;5.2 Parallel Query&quot;">​</a></h3><p>PG 9.6+:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Gather</span></span>
<span class="line"><span>  → Parallel Seq Scan on t</span></span></code></pre></div><p>worker 数：</p><ul><li><code>max_parallel_workers_per_gather = 4</code></li><li><code>max_parallel_workers = 8</code></li><li><code>min_parallel_table_scan_size = 8MB</code></li></ul><p>大表 ≥32GB → 启用并行；小表 seq 一次比启动 worker 启动还快。</p><h3 id="_5-3-adaptive-query-optimization" tabindex="-1">5.3 Adaptive Query Optimization <a class="header-anchor" href="#_5-3-adaptive-query-optimization" aria-label="Permalink to &quot;5.3 Adaptive Query Optimization&quot;">​</a></h3><p>Oracle 12c+ / SQL Server adaptive join：plan tree 留分支，runtime 测 join 选择，动态选 hash vs loop。PG 14+ Partial.</p><h3 id="_5-4-mpp-join-distribution" tabindex="-1">5.4 MPP Join Distribution <a class="header-anchor" href="#_5-4-mpp-join-distribution" aria-label="Permalink to &quot;5.4 MPP Join Distribution&quot;">​</a></h3><p>Greenplum / Spark：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SELECT * FROM A JOIN B ON A.user_id = B.user_id;</span></span></code></pre></div><p>策略：</p><ul><li><strong>Broadcast</strong>：小表 (e.g. &lt; 100MB) 广播到所有节点</li><li><strong>Redistribute</strong>：双表按 join key hash 重分布</li><li><strong>Co-located</strong>：表已按同 key 分布 → 本节点直接 join</li></ul><p>PG Partitioned + Distributed 扩展 (Citus、CockroachDB) 也用类似策略。</p><hr><h2 id="六、产线事故" tabindex="-1">六、产线事故 <a class="header-anchor" href="#六、产线事故" aria-label="Permalink to &quot;六、产线事故&quot;">​</a></h2><h3 id="_6-1-估-rows-不准导致-hash-join-跑爆" tabindex="-1">6.1 估 rows 不准导致 hash join 跑爆 <a class="header-anchor" href="#_6-1-估-rows-不准导致-hash-join-跑爆" aria-label="Permalink to &quot;6.1 估 rows 不准导致 hash join 跑爆&quot;">​</a></h3><p><code>ANALYZE</code> 长时间没跑 → 统计陈旧 → <code>rows=1</code> 估而实际 100 万 → planner 选 nested loop 跑数小时。</p><p><strong>修复</strong>：启用自动 autovacuum + <code>analyze_scale_factor = 0.02</code>；手动 <code>ANALYZE careful_table</code> 每次 ETL 后强刷。</p><h3 id="_6-2-多表-join-geqo-选坏" tabindex="-1">6.2 多表 join GEQO 选坏 <a class="header-anchor" href="#_6-2-多表-join-geqo-选坏" aria-label="Permalink to &quot;6.2 多表 join GEQO 选坏&quot;">​</a></h3><p>BI 工具 18 表 join → GEQO 随机 plan；某些组合 100s 执行。</p><p><strong>修复</strong>：<code>SET geqo = off</code> + <code>SET join_collapse_limit = 50</code>；业务侧汇总预聚合表降 N 表。</p><h3 id="_6-3-random-page-cost-误设-→-全-seq-scan" tabindex="-1">6.3 random_page_cost 误设 → 全 seq scan <a class="header-anchor" href="#_6-3-random-page-cost-误设-→-全-seq-scan" aria-label="Permalink to &quot;6.3 random_page_cost 误设 → 全 seq scan&quot;">​</a></h3><p>某评价改 <code>random_page_cost = 1</code> 走 idx scan 但机械盘上 random IO 慢 → query 1000ms up to 100ms 他选，但实际原 seq 50ms。</p><p><strong>修复</strong>：机械盘 keep 4；SSD 1.1-1.5。</p><h3 id="_6-4-partial-index-predicate-不命中" tabindex="-1">6.4 partial index predicate 不命中 <a class="header-anchor" href="#_6-4-partial-index-predicate-不命中" aria-label="Permalink to &quot;6.4 partial index predicate 不命中&quot;">​</a></h3><p>partial index <code>WHERE active = TRUE</code> 但 SELECT <code>WHERE active IS TRUE</code> 不 match → index not used。</p><p><strong>修复</strong>：PG planner 要求 SELECT predicate logic-imply index predicate，否则不命中。改业务 SQL <code>WHERE active = TRUE</code>。</p><h3 id="_6-5-join-collapse-limit-触发-suboptimal" tabindex="-1">6.5 join_collapse_limit 触发 suboptimal <a class="header-anchor" href="#_6-5-join-collapse-limit-触发-suboptimal" aria-label="Permalink to &quot;6.5 join_collapse_limit 触发 suboptimal&quot;">​</a></h3><p>PG <code>join_collapse_limit = 8</code> (default)，业务写 12 表 join，写顺序入 planner collapse → planner 不重排。</p><p><strong>修复</strong>：<code>SET join_collapse_limit = 50</code> 或 unlimited <code>join_collapse_limit = 0</code>。</p><hr><h2 id="七、易错清单" tabindex="-1">七、易错清单 <a class="header-anchor" href="#七、易错清单" aria-label="Permalink to &quot;七、易错清单&quot;">​</a></h2><ol><li><strong>EXPLAIN cost 不能直觉说&quot;应该是多少 ms&quot;</strong>：dimensions less；仅相对 join 排序规划</li><li><strong>EXPLAIN ANALYZE 实际 vs EXPLAIN 估计巨大 gap</strong> = 统计陈旧/未刷新</li><li><strong>random_page_cost SSD 设 1.1</strong> 不是 4</li><li><strong>default_statistics_target</strong> 大值 (1000+) 让 plan 准确，但 ANALYZE 耗时长</li><li><strong>多表 join ≥ 12 → GEQO</strong>：业务表太多 force off 或 BI 用预聚合 mview</li><li><strong><code>enable_*</code> planner 开关</strong> 禁 hash join/merge：业务调试时慎用</li><li><strong><code>prepare_threshold</code></strong> 在 PG 中复 plan：但 plan 准确性 shaky，需 <code>plan_cache_mode = auto</code> (PG 16+)</li><li><strong>Subquery decorrelation 不是 always optimal</strong> — 取决于实际数据分布</li></ol><hr><h2 id="八、这一章带走的东西" tabindex="-1">八、这一章带走的东西 <a class="header-anchor" href="#八、这一章带走的东西" aria-label="Permalink to &quot;八、这一章带走的东西&quot;">​</a></h2><ol><li>RBO 是 deterministic transformation (pushdown, constant folding, view expansion)、CBO 是 statistics-based search</li><li>PG statistics MCV + histogram + n_distinct 决定 selectivity 估计准确度</li><li>cost model 由 6 个 cpu + page cost 组成，random_page_cost SSD 上必调 1.1</li><li>Plan search = bottom-up DP (System-R) join reorder，N≥12 切 GEQO；大数据用 Cascades</li><li>Cascades (SQL Server, Apache Calcite, CockroachDB, Spark Catalyst) 比单一 DP 强很多</li><li>MPP join: broadcast (小表) / redistribute (大表) / co-located (同分布)</li><li>partition pruning + execution-time pruning 让 1 year partition 12 月表数据 query 走 1 segment</li><li>Planner adaptive join (Oracle/SQL Server 还有 PG partial) 让 runtime 决定 hash vs loop</li></ol><h2 id="下一节-→" tabindex="-1">下一节 → <a class="header-anchor" href="#下一节-→" aria-label="Permalink to &quot;下一节 →&quot;">​</a></h2><p><a href="./join">Join 顺序、hash join vs nested loop</a> — pros cons，Hash Join 临时落盘</p>`,94)])])}const k=s(n,[["render",l]]);export{u as __pageData,k as default};
